        [Fact(DisplayName = "the mains > stay on for a while in a fresh world, are off from the start a year on, and missing on hand-made maps")]
        public void T002_stay_on_for_a_while_in_a_fresh_world_are_off_from_the_start_()
        {
            var fresh = Worldgen.createWorld(3, 64, Js.CopyAs<Settings>(Difficulty.PRESETS["settler"].settings));
            var t = Js.NN(fresh.timeline);
            expect(t.waterOffDay).toBeGreaterThanOrEqual(8);
            expect(t.waterOffDay).toBeLessThanOrEqual(14);
            expect(t.powerOffDay).toBeGreaterThanOrEqual(10);
            expect(TimelineMod.waterOn(fresh) && TimelineMod.powerOn(fresh)).toBe(true);
            fresh.tick = Js.I(startOf(t.waterOffDay));
            expect(TimelineMod.waterOn(fresh)).toBe(false);
            var late = Worldgen.createWorld(3, 64, Js.CopyAs<Settings>(Difficulty.PRESETS["apocalypse"].settings));
            expect(TimelineMod.waterOn(late) || TimelineMod.powerOn(late)).toBe(false);
            expect(Js.NN(late.timeline).helicopterDay).toBe(0);
            expect(TimelineMod.waterOn(ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["..."] }))).toBe(false);
        }

        [Fact(DisplayName = "the mains > kitchen counters, toilets and baths run while the water is on; iceboxes keep cold while the power is")]
        public void T003_kitchen_counters_toilets_and_baths_run_while_the_water_is_on()
        {
            var state = Worldgen.createWorld(3, 128, Js.CopyAs<Settings>(Difficulty.PRESETS["settler"].settings));
            for (var y = 0; y < 128; y += Worldgen.CHUNK)
            {
                for (var x = 0; x < 128; x += Worldgen.CHUNK)
                {
                    Worldgen.ensureGeneratedAround(state, new Point { x = Js.I(x), y = Js.I(y) });
                }
            }
            var tap = state.furniture.find((f) => (f.look == "sink") || (f.look == "counter"));
            var toilet = state.furniture.find((f) => f.look == "toilet");
            var icebox = state.furniture.find((f) => f.look == "icebox");
            expect((Js.T(Js.T(tap) && Js.T(icebox)) ? toilet : null)).toBeTruthy();
            expect(Water.sourceAt(state, Js.NN(tap).x, Js.NN(tap).y)).toBe("tap");
            expect(TimelineMod.isMainsFridge(state, Js.NN(icebox))).toBe(true);
            state.tick = Js.I(startOf(Js.NN(state.timeline).powerOffDay));
            expect(Water.sourceAt(state, Js.NN(tap).x, Js.NN(tap).y)).toBeNull();
            expect(TimelineMod.isMainsFridge(state, Js.NN(icebox))).toBe(false);
            expect(Water.sourceAt(state, Js.NN(toilet).x, Js.NN(toilet).y)).toBe("tank");
            for (var k = 0; k < Js.NN(TimelineMod.TANK_WATER["toilet"]); k++)
            {
                Water.drankFrom(state, "tank", Js.NN(toilet).x, Js.NN(toilet).y);
            }
            expect(Water.sourceAt(state, Js.NN(toilet).x, Js.NN(toilet).y)).toBeNull();
        }

