        [Fact(DisplayName = "happenings > a helicopter comes over on its day, hangs over you, draws the dead, and goes")]
        public void T008_a_helicopter_comes_over_on_its_day_hangs_over_you_draws_the_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = Js.ArrayFrom(40, (int _i) => ".".repeat(40)).map((r, y) => (y == 20) ? ((r.slice(0, 20) + "s") + r.slice(21)) : r) });
            foreach (var k in Js.Iter(Js.ObjectKeys(Js.NN(Js.Get(state.survivors, 0)).priorities)))
            {
                Js.NN(Js.Get(state.survivors, 0)).priorities[Js.Idx(k)] = 0;
            }
            state.timeline = timeline(new Timeline { helicopterDay = 1 });
            state.dormant = [new() { id = "d1", x = Js.I(5), y = Js.I(5) }];
            while (Time.tickOfDay(state.tick) != JsMath.floor(((double)(Time.DAY_LENGTH) * (0.6))))
            {
                state.tick = Js.I(state.tick + 1);
            }
            Tick.tick(state);
            expect(state.timeline.heli).not.toBeNull();
            var over = false;
            for (var i = 0; Js.T((i < 2000) && Js.T(state.timeline.heli)); i++)
            {
                Tick.tick(state);
                var h = state.timeline.heli;
                if ((Js.T(h) && (h.x == 20)) && (h.y == 20))
                {
                    over = true;
                }
            }
            expect(over).toBe(true);
            expect(state.timeline.heli).toBeNull();
            expect(state.dormant).toEqual(Js.Arr([]));
            expect(state.events.some((e) => e.message.includes("helicopter is gone"))).toBe(true);
        }

        [Fact(DisplayName = "happenings > an alarm may go off when a window is smashed with the power on, and rings for a while")]
        public void T009_an_alarm_may_go_off_when_a_window_is_smashed_with_the_power_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s...."] });
            state.timeline = timeline();
            for (var key = 0; (key < 20) && (state.timeline.alarms.length == 0); key++)
            {
                TimelineMod.maybeAlarm(state, new Point { x = Js.I(3), y = Js.I(0) }, key);
            }
            expect(state.timeline.alarms.length).toBe(1);
            for (var i = 0; i <= TimelineMod.ALARM_TICKS; i++)
            {
                Tick.tick(state);
            }
            expect(state.timeline.alarms).toEqual(Js.Arr([]));
            state.timeline.powerOffDay = 1;
            for (var key = 0; key < 20; key++)
            {
                TimelineMod.maybeAlarm(state, new Point { x = Js.I(3), y = Js.I(0) }, key);
            }
            expect(state.timeline.alarms).toEqual(Js.Arr([]));
